const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // Helpers
    const eeGet = (obj) => new Promise((resolve, reject) => obj.evaluate(resolve, reject));
    const pt = ee.Geometry.Point([86.428836, 35.879797]);
    const region = pt.buffer(50000); // 50 km radius
    const primaryStart = '2024-08-11';
    const primaryEnd = '2024-08-12';
    const s2ExpandStart = '2024-08-04';
    const s2ExpandEnd = '2024-08-18';
    const lsExpandStart = '2024-07-28';
    const lsExpandEnd = '2024-08-25';
    const minLakeArea_m2 = 20000; // 0.02 km2
    const ccScale = 100; // reproject water mask to 100 m for connected components
    const reduceScale = 1000; // reduceRegion scale per best practice

    // Masking and index functions
    function maskS2(img) {
      const qa = img.select('QA60');
      const cloudBitMask = 1 << 10;
      const cirrusBitMask = 1 << 11;
      const mask = qa.bitwiseAnd(cloudBitMask).eq(0).and(qa.bitwiseAnd(cirrusBitMask).eq(0));
      return img.updateMask(mask).divide(10000)
        .copyProperties(img, ['CLOUDY_PIXEL_PERCENTAGE', 'SENSING_TIME']);
    }
    function addS2Indices(img) {
      const mndwi = img.select('B3').subtract(img.select('B11')).divide(img.select('B3').add(img.select('B11'))).rename('mndwi');
      const ndvi = img.select('B8').subtract(img.select('B4')).divide(img.select('B8').add(img.select('B4'))).rename('ndvi');
      return img.addBands([mndwi, ndvi]);
    }
    function scaleAndMaskLandsat(img) {
      // Apply scale factors
      const scaled = img.select(['SR_B2','SR_B3','SR_B4','SR_B5','SR_B6','SR_B7'])
                        .multiply(0.0000275).add(-0.2)
                        .rename(['B2','B3','B4','B5','B6','B7']);
      const qa = img.select('QA_PIXEL');
      const mask = qa.bitwiseAnd(1 << 3).eq(0) // Cloud
                    .and(qa.bitwiseAnd(1 << 4).eq(0)) // Cloud shadow
                    .and(qa.bitwiseAnd(1 << 1).eq(0)); // Dilated cloud
      return scaled.updateMask(mask).copyProperties(img, ['CLOUD_COVER', 'DATE_ACQUIRED']);
    }
    function addLsIndices(img) {
      const mndwi = img.select('B3').subtract(img.select('B6')).divide(img.select('B3').add(img.select('B6'))).rename('mndwi');
      const ndvi = img.select('B5').subtract(img.select('B4')).divide(img.select('B5').add(img.select('B4'))).rename('ndvi');
      return img.addBands([mndwi, ndvi]);
    }

    // 1) Collections
    let s2Primary = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(region).filterDate(primaryStart, primaryEnd);
    let s2PrimarySize = await eeGet(s2Primary.size());
    console.log(`Primary S2 imgs: ${s2PrimarySize}`);

    let chosenImg = null;
    let source = null;
    let cloudProp = null;

    if (s2PrimarySize > 0) {
      const s2Sel = s2Primary.map(maskS2).map(addS2Indices).sort('CLOUDY_PIXEL_PERCENTAGE').first().clip(region);
      chosenImg = s2Sel;
      source = 'S2';
      cloudProp = await eeGet(s2Sel.get('CLOUDY_PIXEL_PERCENTAGE'));
    } else {
      const s2Expanded = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
        .filterBounds(region).filterDate(s2ExpandStart, s2ExpandEnd);
      const s2ExpandedSize = await eeGet(s2Expanded.size());
      console.log(`Expanded S2 imgs: ${s2ExpandedSize}`);
      if (s2ExpandedSize > 0) {
        const s2Sel = s2Expanded.map(maskS2).map(addS2Indices).sort('CLOUDY_PIXEL_PERCENTAGE').first().clip(region);
        chosenImg = s2Sel;
        source = 'S2';
        cloudProp = await eeGet(s2Sel.get('CLOUDY_PIXEL_PERCENTAGE'));
      } else {
        const l8 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2').filterBounds(region).filterDate(lsExpandStart, lsExpandEnd);
        const l9 = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2').filterBounds(region).filterDate(lsExpandStart, lsExpandEnd);
        const ls = l8.merge(l9);
        const lsSize = await eeGet(ls.size());
        console.log(`Landsat imgs: ${lsSize}`);
        if (lsSize === 0) {
          console.log('No images found in all windows.');
          console.log('C1');
          return;
        }
        const lsSel = ls.sort('CLOUD_COVER').map(scaleAndMaskLandsat).map(addLsIndices).first().clip(region);
        chosenImg = lsSel;
        source = 'Landsat';
        cloudProp = await eeGet(lsSel.get('CLOUD_COVER'));
      }
    }

    // 2) Valid pixel count after masking (use a band that exists for both)
    const baseBand = source === 'S2' ? 'B3' : 'B3';
    const validPixDict = await eeGet(chosenImg.select(baseBand).reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: region,
      scale: reduceScale,
      maxPixels: 1e9
    }));
    const validPix = validPixDict ? (validPixDict[baseBand] || 0) : 0;
    const cloudStr = cloudProp !== null && cloudProp !== undefined ? Number(cloudProp).toFixed(1) : 'NA';
    console.log(`Using: ${source}, Cloud%: ${cloudStr}, Valid px: ${validPix}`);
    if (!validPix || validPix === 0) {
      console.log('No valid pixels after masking.');
      console.log('C2');
      return;
    }

    // 3) Water mask and lakes counting
    const water = chosenImg.select('mndwi').gt(0.2).and(chosenImg.select('ndvi').lt(0.1));
    // Reproject to coarse resolution for efficient connected components
    const waterRep = water.reproject({crs: chosenImg.projection(), scale: ccScale});
    const minPix = ee.Number(minLakeArea_m2).divide(ee.Number(ccScale).pow(2)).ceil();
    const bigWater = waterRep.updateMask(waterRep).connectedPixelCount(1e7, true).gte(minPix).selfMask();

    // Count connected components (lakes)
    const labels = bigWater.connectedComponents(ee.Kernel.square(1), 1e7);
    const labelCountDict = await eeGet(labels.reduceRegion({
      reducer: ee.Reducer.countDistinct(),
      geometry: region,
      scale: reduceScale,
      maxPixels: 1e9
    }));
    const lakeCount = labelCountDict ? labelCountDict.labels : null;

    console.log(`Lakes (>0.02 km2): ${lakeCount}`);

    // 4) Validation & Final Answer
    if (lakeCount === null || lakeCount === undefined || isNaN(lakeCount)) {
      console.log('C3');
      return;
    }
    if (Number(lakeCount) > 3) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (err) {
    console.log(`Error: ${err}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
